/* ───────── Chip-Gruppe ───────── */
function chips(cfg) {
  var root = el('div', 'hwm-chips'), sel = [], sonst = '', api = {}, sonstBox, sonstIn, plus;
  var multi = cfg.multi !== false;
  function btn(label) {
    var b = el('button', 'hwm-chip', label); b.type = 'button'; b.setAttribute('aria-pressed', 'false'); b.dataset.v = label;
    b.onclick = function () {
      var i = sel.indexOf(label);
      if (i > -1) sel.splice(i, 1);
      else { if (!multi) { sel = []; sonst = ''; sonstIn.value = ''; } sel.push(label); }
      paint(); changed();
    };
    return b;
  }
  function paint() {
    root.querySelectorAll('.hwm-chip[data-v]').forEach(function (b) { b.setAttribute('aria-pressed', sel.indexOf(b.dataset.v) > -1 ? 'true' : 'false'); });
    if (plus) plus.setAttribute('aria-pressed', sonstBox.classList.contains('offen') || sonst ? 'true' : 'false');
  }
  function changed() { if (cfg.onChange) cfg.onChange(api.get()); }
  api.root = root;
  api.get = function () { return sel.concat(sonst ? [sonst] : []); };
  api.set = function (list) {
    sel = []; sonst = ''; var rest = [];
    (list || []).forEach(function (x) {
      var m = api.options.filter(function (o) { return o.toLowerCase() === String(x).toLowerCase(); })[0];
      if (m) { if (sel.indexOf(m) < 0) sel.push(m); } else if (x) rest.push(x);
    });
    if (!multi && sel.length > 1) { rest = rest.concat(sel.slice(1)); sel = sel.slice(0, 1); }
    if (cfg.sonst !== false && rest.length) { sonst = rest.join(', '); sonstIn.value = sonst; sonstBox.classList.add('offen'); }
    else { sonstIn.value = ''; sonstBox.classList.remove('offen'); }
    paint();
  };
  api.setOptions = function (opts) {
    api.options = opts.slice(); var keep = api.get();
    root.querySelectorAll('.hwm-chip[data-v]').forEach(function (b) { b.remove(); });
    opts.forEach(function (o) { root.insertBefore(btn(o), plus || sonstBox); });
    api.set(keep); paint();
  };
  sonstBox = el('div', 'hwm-sonst'); sonstIn = el('input'); sonstIn.type = 'text';
  sonstIn.placeholder = cfg.sonstPlatz || 'Eigene Angabe …'; sonstIn.setAttribute('aria-label', cfg.sonstLabel || 'Sonstiges');
  sonstIn.addEventListener(cfg.commit ? 'change' : 'input', function () { sonst = sonstIn.value.trim(); paint(); changed(); });
  sonstBox.appendChild(sonstIn);
  if (cfg.sonst !== false) {
    plus = el('button', 'hwm-chip hwm-plus', cfg.sonstLabel || '+ Sonstiges'); plus.type = 'button'; plus.setAttribute('aria-pressed', 'false');
    plus.onclick = function () { sonstBox.classList.toggle('offen'); if (sonstBox.classList.contains('offen')) sonstIn.focus(); paint(); };
    root.appendChild(plus);
  }
  root.appendChild(sonstBox);
  api.options = [];
  api.setOptions(cfg.options || []);
  return api;
}

/* Chip-Gruppe an ein bestehendes Feld binden: Feld wird versteckt, Wert bleibt im Feld (Autospeichern + Abnehmer unverändert) */
function bind(target, cfg) {
  if (!target || target.dataset.hwm) return null;
  target.dataset.hwm = '1';
  var sep = cfg.sep || ', ';
  var g = chips({ options: cfg.options, multi: cfg.multi, sonst: cfg.sonst, sonstLabel: cfg.sonstLabel, sonstPlatz: cfg.sonstPlatz,
    onChange: function (l) { target.value = l.join(sep); fire(target); if (cfg.onChange) cfg.onChange(l); } });
  target.classList.add('hwm-weg');
  target.parentNode.insertBefore(g.root, target.nextSibling);
  g.sync = function () { g.set(target.value ? target.value.split(sep === ', ' ? /,\s*/ : sep) : []); };
  g.target = target; g.sync();
  target.__hwm = g;
  return g;
}
function allSync() { document.querySelectorAll('[data-hwm]').forEach(function (t) { if (t.__hwm) t.__hwm.sync(); }); }

/* Eigenes Auswahl-Feld (kein bestehendes Feld) mit eigener Speicherung über ein verstecktes Textfeld */
function neu(id, label, cfg, wo, opt) {
  var blk = el('div', 'hwm-block field'), h = el('label', 'hwm-h', label);
  if (opt) { var o = el('span', 'hwm-opt', ' (optional)'); h.appendChild(o); }
  var inp = el('input'); inp.type = 'text'; inp.id = id; inp.className = 'hwm-weg';
  blk.appendChild(h); blk.appendChild(inp); wo(blk);
  var g = bind(inp, cfg); return { blk: blk, inp: inp, g: g };
}
function vorn(parent) { return function (b) { parent.insertBefore(b, parent.firstChild); }; }
function ende(parent) { return function (b) { parent.appendChild(b); }; }
function vor(ref) { return function (b) { ref.parentNode.insertBefore(b, ref); }; }
