  if (ART === 'webdesign' && d.website && $('web-toggle') && !$('web-toggle').classList.contains('on')) { try { toggleCond('web-toggle', 'web-cond'); } catch (e) { } }
  if (d.gewerk && ART === 'webdesign' && $('wdGewerk') && !$('wdGewerk').value) { $('wdGewerk').value = gewerkTitel([].concat(d.gewerk)).join(' | '); $('wdGewerk').classList.add('hwm-vorbelegt'); vorbelegtFelder.push('wdGewerk'); }
