  var step = $(ART === 'webdesign' ? 'step-company' : 'step-company');
  var box = el('div', 'hwm-vor'), t = el('span'); t.innerHTML = '<b>Wir haben schon etwas für euch ausgefüllt.</b> Bitte kurz prüfen und bei Bedarf ändern.';
  var ok = el('button', 'hwm-chip', 'Stimmt so'); ok.type = 'button'; ok.setAttribute('aria-pressed', 'false'); ok.id = 'hwmBestaetigt';
  ok.onclick = function () { ok.setAttribute('aria-pressed', ok.getAttribute('aria-pressed') === 'true' ? 'false' : 'true'); };
  box.appendChild(t); box.appendChild(ok);
