/* ───────── Sammlung: neue Antworten in das bestehende Format einhängen ───────── */
function nachSchluessel(data, anker, paare, vorSektion) {
  var out = {}, done = false;
  Object.keys(data).forEach(function (k) {
    if (!done && vorSektion && k.indexOf('── ' + vorSektion) === 0) { paare.forEach(function (p) { if (p[1]) out[p[0]] = p[1]; }); done = true; }
    out[k] = data[k];
    if (!done && anker && k === anker) { paare.forEach(function (p) { if (p[1]) out[p[0]] = p[1]; }); done = true; }
  });
  if (!done) paare.forEach(function (p) { if (p[1]) out[p[0]] = p[1]; });
  return out;
}
function w(id) { var e = $(id); return e ? (e.value || '').trim() : ''; }
function sektion(data, titel, paare, vorSektion) {
  var p = paare.filter(function (x) { return x[1]; }); if (!p.length) return data;
  var neu_ = [['── ' + titel + ' ──', '']].concat(p);
  var out = {}, done = false;
  Object.keys(data).forEach(function (k) {
    if (!done && vorSektion && k.indexOf('── ' + vorSektion) === 0) { neu_.forEach(function (x) { out[x[0]] = x[1]; }); done = true; }
    out[k] = data[k];
  });
  if (!done) neu_.forEach(function (x) { out[x[0]] = x[1]; });
  return out;
}
function wrapSammlung() {
  if (typeof collectFormData !== 'function') return;
  var orig = collectFormData;
  collectFormData = function () {
    var d = orig();
    var best = $('hwmBestaetigt');
    if (ART === 'webdesign') {
      d = nachSchluessel(d, 'Ort', [['Gewerk', w('wdGewerk').split(' | ').join(' + ')]]);
      d = sektion(d, 'ZIELGRUPPE & BETRIEB', [['Zielkunden', w('hwmZielkunden')], ['Wunsch-Aufträge', w('hwmWunsch')], ['Typische Auftragsgröße', w('hwmAuftrag')],
        ['Mitarbeiterzahl', w('hwmMitarb')], ['Einzugsgebiet (Umkreis)', w('hwmKm')], ['Ansprache auf der Website', w('hwmAnsprache')]], 'ÖFFNUNGSZEITEN');
      d = sektion(d, 'LOGO & FARBEN', [['Logo', w('hwmLogoStatus')], ['Farbwünsche', w('hwmFarben')]], 'SONSTIGES');
      var ta = $('wdWasMacht'); if (ta && ta.dataset.auto === '1' && !textEigen) d = nachSchluessel(d, 'Was macht ihr genau?', [['  Text automatisch aus der Auswahl erstellt', 'Ja']]);
    } else {
      d = nachSchluessel(d, 'Ort', [['Gewerk', SHKTITEL]]);
      d = sektion(d, 'ZIELGRUPPE & BETRIEB', [['Zielkunden', w('hwmZielkunden')], ['Mitarbeiterzahl', w('hwmMitarb')], ['Ansprache in Anzeigen', w('hwmAnsprache')]], 'RECRUITING');
      d = sektion(d, 'LOGO & FARBEN', [['Logo', w('hwmLogoStatus')], ['Farbwünsche', w('hwmFarben')]], 'ERKLÄRUNGEN');
    }
    if (window.__hwmToken) d = sektion(d, 'VORAUSGEFÜLLT', [['Vorausgefüllte Angaben bestätigt', best && best.getAttribute('aria-pressed') === 'true' ? 'Ja' : 'Nein, nicht bestätigt']], 'ERKLÄRUNGEN');
    return d;
  };
  var om = collectMissing;
  collectMissing = function (l) {
    var m = om(l);
    if (ART === 'webdesign' && !w('wdGewerk')) m.unshift('Gewerk');
    return m;
  };
}

/* ───────── Start ───────── */
function start() {
  if (ART === 'webdesign') aufbauWebdesign(); else aufbauShk();
  wrapSammlung();
  restoreNeu();
  try { if (window.UX_CFG) { window.UX_CFG.map = window.UX_CFG.map || {}; window.UX_CFG.map['Gewerk'] = 'step-company'; } } catch (e) { }
  ladeVorbelegung(function () {
    allSync();
    if (ART === 'webdesign') {
      if (window.__hwmLeist) window.__hwmLeist.refresh();
      // Leistungen aus dem Entwurf: Karten haben Namen, Auswahl daraus spiegeln, Stichpunkt-Chips an alle Karten
      document.querySelectorAll('.leistung-item').forEach(function (it) { var n = it.querySelector('.leistung-name'); if (n && n.value.trim()) { it.dataset.hwmChip = '1'; spChips(it, n.value.trim()); } });
      Array.prototype.slice.call(document.querySelectorAll('.leistung-item')).forEach(function (it) { if (itemLeer(it)) it.remove(); });
      (window.__hwmVorAktiv || []).forEach(function (n) { var ex = itemNamen().map(function (x) { return x.toLowerCase(); }); if (ex.indexOf(n.toLowerCase()) < 0) neueLeistung(n).dataset.hwmChip = '1'; });
      if (window.__hwmLeist) window.__hwmLeist.refresh();
      nummerieren(); fuelleWunsch(); zusammenfassen();
    }
  });
}
// loadDraft läuft im load-Ereignis der Seite; wir hängen uns danach an
